/bin/bash -c "python3 - <<'PY'
from pypdf import PdfReader
r=PdfReader('manuscript.pdf')
uris=set()
for p in r.pages:
    for a in p.get('/Annots',[]):
        obj=a.get_object()
        act=obj.get('/A',{})
        if hasattr(act,'get_object'): act=act.get_object()
        if act.get('/URI'): uris.add(str(act['/URI']))
print('\\n'.join(sorted(uris)))
PY"
